settings.custom_liquid:
{% assign sold_percent = 93 %}

<div class="sf-wrap">
  <div class="sf-row">
    <span class="sf-icon" aria-hidden="true">
      <svg viewBox="0 0 24 24" width="14" height="14" fill="none" xmlns="http://www.w3.org/2000/svg">
        <path d="M12.4 2.6c.2 3.2-1.3 5-3.1 6.7C7.6 10.9 6 12.5 6 15.1 6 19 9.1 22 13 22s7-3 7-6.9c0-3.6-2.2-5.6-3.9-7.3-1.3-1.3-2.3-2.7-2.6-5.3"
              stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
      </svg>
    </span>

    <span class="sf-text">Selling out fast</span>
    <span class="sf-pct">{{ sold_percent }}% sold</span>
  </div>

  <div class="sf-bar">
    <span class="sf-fill" style="width: {{ sold_percent }}%"></span>
  </div>
</div>

<style>
/* isolated namespace to avoid theme collisions */
.sf-wrap{
  margin-top:12px;
  font-family: inherit;
}

.sf-row{
  display:flex;
  align-items:center;
  gap:6px;
  font-size:12px;
  color:#111;
  margin-bottom:6px;
}

.sf-icon{
  display:inline-flex;
  align-items:center;
  color:#111;
}

.sf-text{
  font-weight:600;
  text-transform:uppercase;
  letter-spacing:.4px;
}

.sf-pct{
  margin-left:auto;
  font-weight:500;
  color:rgba(0,0,0,.6);
}

.sf-bar{
  position:relative;
  height:6px;
  background:rgba(0,0,0,.08);
  border-radius:999px;
  overflow:hidden;
}

/* CRITICAL: span + display:block prevents theme resets */
.sf-fill{
  display:block !important;
  height:100% !important;
  width: {{ sold_percent }}% !important;
  background:#111 !important;
  border-radius:999px;
}
</style>
